<?php require_once __DIR__.'/../includes/auth.php'; require_role(['admin']); $pageTitle='Manage Users'; require __DIR__.'/../includes/header.php'; $rows=$pdo->query('SELECT id,full_name,email,role,is_active,created_at FROM users ORDER BY created_at DESC')->fetchAll();echo '<h1>Manage users</h1><p>Role changes should only be made by authorized administrators. Account editing actions are a next implementation step.</p><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th><th>Created</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['full_name']).'</td><td>'.e($r['email']).'</td><td>'.e($r['role']).'</td><td>'.($r['is_active']?'Yes':'No').'</td><td>'.e($r['created_at']).'</td></tr>';}echo '</table></div>'; require __DIR__.'/../includes/footer.php'; ?>